<?php get_header(); ?><main class="container content-area py-5"><header class="page-heading"><span class="kicker">DISCOVER</span><h1><?php the_archive_title(); ?></h1><?php the_archive_description(); ?></header><div class="row g-4"><?php if(have_posts()):while(have_posts()):the_post(); ?><div class="col-md-6 col-lg-4"><article class="article-card h-100"><?php if(has_post_thumbnail())the_post_thumbnail('medium',array('class'=>'img-fluid rounded mb-3')); ?><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?><a class="text-arrow" href="<?php the_permalink(); ?>">Read more</a></article></div><?php endwhile;else: ?><p>No entries.</p><?php endif; ?></div><?php newtheme_pagination(); ?></main><?php get_footer(); ?>